-- Dumping structure for table world_test.felskorn_talents
DROP TABLE IF EXISTS `felskorn_talents`;
CREATE TABLE IF NOT EXISTS `felskorn_talents` (
  `class_id` tinyint unsigned NOT NULL,
  `tab_id` tinyint unsigned NOT NULL,
  `spell_id` int unsigned NOT NULL,
  `item_type` varchar(16) NOT NULL DEFAULT 'spell',
  `row_pos` tinyint unsigned NOT NULL,
  `column_pos` tinyint unsigned NOT NULL,
  `talent_type` varchar(16) NOT NULL DEFAULT 'spec',
  `required_spell_1` int unsigned NOT NULL DEFAULT '0',
  `required_spell_2` int unsigned NOT NULL DEFAULT '0',
  `required_spell_3` int unsigned NOT NULL DEFAULT '0',
  `node_style` tinyint unsigned NOT NULL DEFAULT '0',
  `node_height` tinyint unsigned NOT NULL DEFAULT '0',
  `enabled` tinyint unsigned NOT NULL DEFAULT '1',
  `comment` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`class_id`,`tab_id`,`spell_id`),
  KEY `idx_felskorn_talents_class_tab` (`class_id`,`tab_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

