-- Dumping structure for table world_test.felskorn_talent_tabs
DROP TABLE IF EXISTS `felskorn_talent_tabs`;
CREATE TABLE IF NOT EXISTS `felskorn_talent_tabs` (
  `class_id` tinyint unsigned NOT NULL,
  `tab_id` tinyint unsigned NOT NULL,
  `name` varchar(64) NOT NULL,
  `tp` smallint unsigned NOT NULL DEFAULT '0',
  `max_active_spells` tinyint unsigned NOT NULL DEFAULT '1',
  `icon` varchar(128) NOT NULL,
  `background` varchar(255) NOT NULL,
  `enabled` tinyint unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`class_id`,`tab_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

